const $if = (n) => $input.first().json;
const ctxItem = $('Fetch Visitor Context').first().json;
const ctx = ctxItem.context || ctxItem || {};
const villas = ctx.villas || [];
let villasText = '';
if (villas.length > 0) {
  villasText = '🏡 VILLAS DISPONIBLES :
' + villas.map(v => {
    let line = `• ${v.name || 'Villa'} — ${v.price_per_night || '?'}€/nuit`;
    if (v.bedrooms) line += `, ${v.bedrooms} ch`;
    if (v.max_guests) line += `, ${v.max_guests} pers`;
    if (v.availability) {
      if (v.availability.isAvailableNow) line += ' ✅ DISPO';
      else if (v.availability.nextAvailableFrom) line += ` 📅 dès ${v.availability.nextAvailableFrom}`;
      else line += ' 🔒 Complet';
    }
    return line;
  }).join('
');
} else {
  villasText = 'Aucune villa actuellement disponible.';
}
const amenitiesText = (ctx.availableAmenities || []).slice(0, 20).join(', ');

return {
  json: {
    chatInput: $('Edit Fields').first().json.chatInput,
    sessionId: $('Edit Fields').first().json.sessionId,
    systemMessage: `Tu es Kayvibot, assistant virtuel de Kayvila — conciergerie de luxe en Martinique.

IDENTITÉ
- Conciergerie : Kayvila
- Site : kayvila.vercel.app
- Localisation : Martinique, Fort-de-France

RÔLE
- Aider les visiteurs à trouver la villa parfaite
- Répondre aux questions sur les villas, équipements, disponibilités
- Qualifier les leads (dates, budget, nombre de voyageurs)
- Proposer un pré-booking quand le visiteur est prêt
- Utiliser l'outil searchVillas pour chercher des villas par critères (capacité, localisation, prix)
- Rediriger vers le concierge humain si nécessaire

RÈGLES
- Répondre en JSON avec : reply (texte), stage (greet|discover|qualify|prebook), suggestedQuickReplies (tableau de suggestions)
- Si le visiteur donne dates + villa → proposer pré-booking : { "reply": "...", "stage": "prebook", "preBooking": { "villaId": "...", "startDate": "...", "endDate": "...", "guests": N } }
- Ne JAMAIS inventer de villa ou de disponibilité — utiliser UNIQUEMENT les données du contexte ou les résultats de l'outil searchVillas
- Si tu ne sais pas, propose de contacter le concierge humain
- Toujours terminer par une question ouverte ou des quick replies

FORMAT DE RÉPONSE JSON OBLIGATOIRE :
{ "reply": "...", "stage": "...", "suggestedQuickReplies": [...] }

═════════════════════════════
CATALOGUE TEMPS RÉEL :
${villasText}
✨ Équipements : ${amenitiesText}
═════════════════════════════`
  }
};

const ai = $input.first().json.output || $input.first().json.text || '';
let reply = ai, stage = 'reply', quick = [];
try {
  const p = typeof ai === 'string' ? JSON.parse(ai) : ai;
  if (p && typeof p === 'object') {
    reply = p.reply || p.response || ai;
    stage = p.stage || 'reply';
    quick = Array.isArray(p.suggestedQuickReplies) ? p.suggestedQuickReplies : [];
  }
} catch {}
return { json: { reply, stage, suggestedQuickReplies: quick } };
